<!-- Modified for Identale; see the root NOTICE. -->
<script setup lang="ts">
import{ref,watch,onBeforeUnmount,computed}from'vue';import{NCard,NButton,NInput,NSelect}from'naive-ui';import{api,errorMessage}from'../../shared/api';
import DirectoryRulePicker from '../directory/DirectoryRulePicker.vue';import type{DirectoryAccessRule,DirectorySubjects}from'../directory/types';
const props=defineProps<{base:string}>();const emit=defineEmits<{dirtyChanged:[boolean];busyChanged:[boolean]}>();type Target={kind:string;userId:string;[k:string]:unknown};type Rule={questionScope:string;target:Target};type Candidate={label:string;target:Target};
const subjects=ref<DirectorySubjects>({sources:[],users:[],departments:[]}),browse=ref(false);const version=ref(0),rules=ref<Rule[]>([]),candidates=ref<Candidate[]>([]),busy=ref(false),error=ref(''),notice=ref(''),dirty=ref(false);let controller=new AbortController();
const options=computed(()=>candidates.value.map(x=>({label:x.label,value:JSON.stringify(x.target)})));
async function load(){controller.abort();controller=new AbortController();const signal=controller.signal;busy.value=true;error.value='';try{const r=await api<{version:number;rules:Rule[];candidates:Candidate[];subjects:DirectorySubjects}>(props.base+'/human-confirmation',signal);if(signal.aborted)return;version.value=r.version;rules.value=r.rules;candidates.value=r.candidates;subjects.value=r.subjects;dirty.value=false;}catch(e){if(!signal.aborted)error.value=errorMessage(e);}finally{if(!signal.aborted)busy.value=false;}}
async function save(){if(busy.value)return;const signal=controller.signal;busy.value=true;error.value='';notice.value='';try{const r=await api<{version:number;rules:Rule[]}>(props.base+'/human-confirmation',signal,{expectedVersion:version.value,rules:rules.value},'PUT');if(signal.aborted)return;version.value=r.version;rules.value=r.rules;dirty.value=false;notice.value='人工确认接收人已保存。';}catch(e){if(!signal.aborted)error.value=errorMessage(e);}finally{if(!signal.aborted)busy.value=false;}}
async function choosePerson(values:DirectoryAccessRule[]){const signal=controller.signal,choice=values[0];if(!choice||choice.kind!=='channel_user')return;error.value='';try{const current=await api<{candidates:Candidate[]}>(props.base+'/human-confirmation',signal);if(signal.aborted)return;candidates.value=current.candidates;const parts=JSON.parse(choice.subjectId)as string[],source=subjects.value.sources.find(x=>x.sourceId===choice.sourceId),match=current.candidates.find(x=>x.target.kind==='channel'&&x.target.connectionId===source?.id&&x.target.userId===parts[3]&&x.target.identityNamespace===parts[1]);if(!match)throw Error('person_not_available');rules.value.push({questionScope:rules.value.length?'':'*',target:match.target});dirty.value=true;browse.value=false;}catch(e){if(!signal.aborted)error.value=errorMessage(e);}}
function add(){const first=candidates.value[0];if(first){rules.value.push({questionScope:rules.value.length?'':'*',target:first.target});dirty.value=true;}}
watch(dirty,v=>emit('dirtyChanged',v),{flush:'sync'});watch(busy,v=>emit('busyChanged',v),{flush:'sync'});
watch(()=>props.base,()=>{rules.value=[];candidates.value=[];subjects.value={sources:[],users:[],departments:[]};dirty.value=false;browse.value=false;notice.value='';void load();},{immediate:true});onBeforeUnmount(()=>{controller.abort();emit('dirtyChanged',false);emit('busyChanged',false);});
</script>
<template><NCard class="human-settings" title="人工确认" size="small"><p class="field-note">按问题范围指定一位确认人，* 作为兜底。未接入渠道且未配置时，发给创建人的平台对话；已接入渠道时请明确指定。确认人须有员工使用权；渠道确认人须有私聊使用权。</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-for="(rule,index) in rules" :key="index" class="human-rule"><NInput v-model:value="rule.questionScope" :disabled="busy" placeholder="问题范围或 *" :input-props="{'aria-label':'确认问题范围'}" @update:value="dirty=true"/><NSelect :value="JSON.stringify(rule.target)" :options="options" filterable :disabled="busy" aria-label="确认接收人" @update:value="value=>{rule.target=JSON.parse(value);dirty=true;}"/><NButton :disabled="busy" @click="rules.splice(index,1);dirty=true">移除</NButton></div><p v-if="!rules.length" class="field-note">尚未设置专门接收人。</p><DirectoryRulePicker v-if="browse" :base="base" :rules="[]" :subjects="subjects" select-people-only label="人工确认人" @update:rules="choosePerson"/><div class="human-actions"><NButton v-if="subjects.sources.length" :disabled="busy" @click="browse=!browse">{{browse?'收起渠道目录':'从渠道目录选择'}}</NButton><NButton :disabled="busy||!candidates.length" @click="add">添加确认规则</NButton><NButton :disabled="busy" @click="load">{{dirty?'放弃更改':'刷新候选'}}</NButton><NButton type="primary" :loading="busy" :disabled="!dirty||busy||rules.some(r=>!r.questionScope.trim())" @click="save">保存确认设置</NButton></div><p v-if="dirty" class="field-note" role="status">有未保存的确认设置。</p></NCard></template>
<style scoped>.human-settings{min-width:0}.human-rule{display:grid;grid-template-columns:minmax(8rem,1fr) minmax(12rem,2fr) auto;gap:.75rem;margin:.75rem 0}.human-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem}@media(max-width:47.5rem){.human-rule{grid-template-columns:1fr}.human-rule>.n-button{justify-self:start}}</style>
